CREATE SCHEMA pn10;
COMMENT ON SCHEMA pn10 IS 'Banco de dados relacional';

SET search_path TO pn10;

create table usuario (
  	codigo serial primary key,
	nome varchar(80) not null,
	ativo boolean not null,
	email varchar(255) not null,
	senha varchar(255) not null,
	data_cadastro timestamptz not null,
	data_atualizacao timestamptz not null,
	motivo_inativacao varchar(500),
	tipo_usuario varchar(30) not null,
	deletado boolean default false,
	codigo_usuario_cadastro integer not null,
	codigo_usuario_atualizacao integer not null,
	avaliacao_media double precision,
	codigo_pessoa integer,
	codigo_empresa integer,

 	foreign key (codigo_usuario_cadastro) references usuario(codigo),
	foreign key (codigo_usuario_atualizacao) references usuario(codigo)
);

create table estado(
   codigo serial primary key,
   sigla varchar(2) not null,
   nome  varchar(50) not null,
   data_cadastro timestamptz not null,
   data_atualizacao timestamptz not null,
   codigo_usuario_cadastro integer not null,
   codigo_usuario_atualizacao integer not null,
   deletado boolean default false,
   foreign key (codigo_usuario_cadastro) references usuario(codigo),
   foreign key (codigo_usuario_atualizacao) references usuario(codigo)
);

create table cidade(
       codigo serial primary key,
       nome   varchar(50) not null,
    codigo_estado integer not null,
   deletado boolean default false,
   foreign key (codigo_estado) references estado(codigo),
   data_cadastro timestamptz not null,
   data_atualizacao timestamptz not null,
   codigo_usuario_cadastro integer not null,
   codigo_usuario_atualizacao integer not null,
   foreign key (codigo_usuario_cadastro) references usuario(codigo),
   foreign key (codigo_usuario_atualizacao) references usuario(codigo)
);

create table grupo (
	codigo serial primary key,
	nome varchar(60) not null,
	data_cadastro timestamptz not null,
	data_atualizacao timestamptz not null,
	codigo_usuario_cadastro integer not null,	
	codigo_usuario_atualizacao integer not null,
	deletado boolean default false,
	foreign key (codigo_usuario_cadastro) references usuario(codigo),
	foreign key (codigo_usuario_atualizacao) references usuario(codigo)
);

create table usuario_grupo (
	codigo_usuario integer not null,
	codigo_grupo integer not null,
	primary key (codigo_usuario, codigo_grupo),
	foreign key (codigo_usuario) references usuario(codigo),
	foreign key (codigo_grupo) references grupo(codigo)
) ;


create table permissao (
   codigo serial primary key ,
   descricao varchar(60) not null,
   nome varchar(100) not null,
   data_cadastro timestamptz not null,
   data_atualizacao timestamptz not null,
   codigo_usuario_cadastro integer not null,
   codigo_usuario_atualizacao integer not null,
   foreign key (codigo_usuario_cadastro) references usuario(codigo),
   foreign key (codigo_usuario_atualizacao) references usuario(codigo)
);

create table grupo_permissao (
	codigo_grupo integer not null,
	codigo_permissao integer not null,
	primary key (codigo_grupo, codigo_permissao),
	foreign key (codigo_grupo) references grupo(codigo),
	foreign key (codigo_permissao) references permissao(codigo)
);

create table token_resetar_senha(
     token varchar(256) primary key,
     codigo_usuario integer not null,
     data_expiracao timestamptz not null,
     expirado boolean not null default false,
     foreign key (codigo_usuario) references usuario(codigo),
   data_cadastro timestamptz not null,
   data_atualizacao timestamptz not null,
   codigo_usuario_cadastro integer not null,
   codigo_usuario_atualizacao integer not null,
   foreign key (codigo_usuario_cadastro) references usuario(codigo),
   foreign key (codigo_usuario_atualizacao) references usuario(codigo) 		
);

create table oauth_client_details (
  client_id varchar(255) primary key,
  resource_ids varchar(256),
  client_secret varchar(256),
  scope varchar(256),
  authorized_grant_types varchar(256),
  web_server_redirect_uri varchar(256),
  authorities varchar(256),
  access_token_validity integer,
  refresh_token_validity integer,
  additional_information varchar(4096),
  autoapprove varchar(256)
);

create table tipo_contato (
  codigo serial primary key,
  descricao varchar(45)  not null,
   data_cadastro timestamptz not null,
   data_atualizacao timestamptz not null,
   codigo_usuario_cadastro integer not null,
   codigo_usuario_atualizacao integer not null,
	deletado boolean default false,
   foreign key (codigo_usuario_cadastro) references usuario(codigo),
   foreign key (codigo_usuario_atualizacao) references usuario(codigo)
);

create table contato (
  codigo serial primary key,
  telefone_fixo varchar(15),
  telefone_celular varchar(15)  not null,
  email varchar(45) not null,
  contato_principal boolean not null,
  codigo_tipo_contato integer not null,
	deletado boolean default false,
  foreign key (codigo_tipo_contato) references tipo_contato(codigo) 	,
   data_cadastro timestamptz not null,
   data_atualizacao timestamptz not null,
   codigo_usuario_cadastro integer not null,
   codigo_usuario_atualizacao integer not null,
   foreign key (codigo_usuario_cadastro) references usuario(codigo),
   foreign key (codigo_usuario_atualizacao) references usuario(codigo)
);

