   codigo_usuario_cadastro integer not null,
   codigo_usuario_atualizacao integer not null,
   codigo_imagem integer,
   deletado boolean default false,
   foreign key (codigo_usuario_cadastro) references usuario(codigo),
   foreign key (codigo_usuario_atualizacao) references usuario(codigo),
foreign key (codigo_imagem) references arquivo(codigo)
);

create table subcategoria_servico(
   codigo serial primary key,
   codigo_categoria_servico integer not null,
   descricao varchar(50) not null,
   data_cadastro timestamptz not null,
   deletado boolean default false,
   data_atualizacao timestamptz not null,
   codigo_usuario_cadastro integer not null,
   codigo_usuario_atualizacao integer not null,
   foreign key (codigo_usuario_cadastro) references usuario(codigo),
   foreign key (codigo_usuario_atualizacao) references usuario(codigo),
   foreign key (codigo_categoria_servico) references categoria_servico(codigo)
);


create table usuario_pessoa (
	codigo_usuario integer not null,
	codigo_pessoa integer not null,
	foreign key (codigo_usuario) references usuario(codigo),
	foreign key (codigo_pessoa) references pessoa(codigo)
);

create table usuario_empresa (
	codigo_usuario integer not null,
	codigo_empresa integer not null,
	foreign key (codigo_usuario) references usuario(codigo),
	foreign key (codigo_empresa) references empresa(codigo)
);


create table plano(
	codigo serial primary key,
	ativo boolean not null default true,
	deletado boolean default false,
	descricao varchar(150) not null,
	limite_clientes_mensal integer NOT NULL,
	data_cadastro timestamptz not null,
	data_atualizacao timestamptz not null,
	codigo_usuario_cadastro integer not null,
	codigo_usuario_atualizacao integer not null,
	foreign key (codigo_usuario_cadastro) references usuario(codigo),
	foreign key (codigo_usuario_atualizacao) references usuario(codigo)
);

create table integracao(
    codigo serial primary key, 
    ativo boolean not null default true,
    deletado boolean default false,
    chave_postback varchar(36) not null,  
    plataforma_integracao varchar(40) not null,
    data_cadastro timestamptz not null,
	data_atualizacao timestamptz not null,
    descricao varchar(100),
    api_key_token varchar(100),
    identificador_produto varchar(100), -- Id, Codigo ou Chave do produto cadastrado na plataforma escolhida
    url_checkout varchar(100), -- Na plataforma
    
    codigo_usuario_cadastro integer not null,
	codigo_usuario_atualizacao integer not null,
    codigo_plano integer not null, --  Plano interno do sistema.
    foreign key (codigo_usuario_cadastro) references usuario(codigo),
	foreign key (codigo_usuario_atualizacao) references usuario(codigo),
    foreign key(codigo_plano) references plano(codigo)  
);


create table subcategoria_servico_prestador(
   codigo_subcategoria_servico integer not null,
   codigo_prestador integer not null,
   foreign key (codigo_subcategoria_servico) references subcategoria_servico(codigo),
   foreign key (codigo_prestador) references usuario(codigo)
);


alter table usuario add column codigo_plano integer;
alter table usuario add constraint fk_plano foreign key(codigo_plano) references plano(codigo);

