create table agenda(
	codigo serial primary key,
	codigo_prestador integer not null,
	
	inicio_periodo_matituno varchar(20) not null,
	fim_periodo_matituno varchar(20) not null,

	inicio_periodo_vespertino varchar(20) not null,
	fim_periodo_vespertino varchar(20) not null,

	inicio_periodo_noturno varchar(20) not null,
	fim_periodo_noturno varchar(20) not null,

	atende_feriado boolean not null,
	atende_dias_semana varchar(100) not null CHECK(atende_dias_semana in('SEGUNDA_FEIRA','TERCA_FEIRA','QUARTA-FEIRA', 'QUINTA_FEIRA','SEXTA_FEIRA','SABADO','DOMINGO')) ,

	max_agendamento_diario integer,
	tempo_minutos_entre_atendimentos integer,
	
	data_cadastro timestamptz not null,
	data_atualizacao timestamptz not null,
	
	codigo_usuario_cadastro integer not null,
	codigo_usuario_atualizacao integer not null,
	
	foreign key (codigo_prestador) references usuario(codigo),
	foreign key (codigo_usuario_cadastro) references usuario(codigo),
	foreign key (codigo_usuario_atualizacao) references usuario(codigo)
);

create table bloqueio_agenda(
	codigo serial primary key,
	codigo_agenda integer not null,
	inicio_vigencia timestamptz,
	fim_vigencia timestamptz,
	motivo_bloqueio text,
	foreign key (codigo_agenda) references agenda(codigo)
);

create table agendamento(
	codigo serial primary key,
	codigo_agenda integer not null,
	data timestamptz not null,

	data_cadastro timestamptz not null,
	data_atualizacao timestamptz not null,
	codigo_usuario_atualizacao integer not null,
	codigo_usuario_cadastro integer not null,
	foreign key (codigo_agenda) references agenda(codigo),
	foreign key (codigo_usuario_cadastro) references usuario(codigo),
	foreign key (codigo_usuario_atualizacao) references usuario(codigo)
);


-- ----------------------------------------------------------------------------
-- Origem: common/V004__cria_tabela_pedidos.sql
-- ----------------------------------------------------------------------------
/*
*
*   AGUARDANDO_ORCAMENTO : Quando o cliente cria um pedido
*   AGUARDANDO_AGENDAMENTO : Quando um orçamento foi escolhido e o cliente precisa fazer o agendamento, de acordo com horários da agenda do prestador
*   AGUARDANDO_ATENDIMENTO : Quando o cliente fecha orçamento com o prestador
*   FINALIZADO_AGUARDANDO_AVALIACAO : Quando o prestador finaliza o serviço o cliente deve avaliar o prestador
*   FINALIZADO : Quando o serviço é finalizado pelo prestador e avaliado pelo cliente
*   CANCELADO : Cliente cancela o pedido
*/

create table pedido(
   codigo serial primary key,
   descricao text not null,
   situacao varchar(50) not null,

   endereco_atendimento_logradouro varchar(50)  not null,
   endereco_atendimento_numero varchar(15)  not null,
   endereco_atendimento_cep varchar(20)  not null,
   endereco_atendimento_complemento varchar(30),
   endereco_atendimento_latitude decimal,
   endereco_atendimento_longitude decimal, 
   endereco_atendimento_bairro varchar(60)  not null,
   endereco_atendimento_codigo_cidade integer not null,	
  
	codigo_cliente integer not null,

	codigo_orcamento_selecionado integer , 
	
	codigo_agendamento integer,
	data_finalizacao_atendimento timestamptz,
	
	data_cadastro timestamptz not null,
	data_atualizacao timestamptz not null,
	codigo_usuario_cadastro integer not null,
	codigo_usuario_atualizacao integer not null,
	
	foreign key (endereco_atendimento_codigo_cidade) references cidade(codigo),
	foreign key (codigo_cliente) references usuario(codigo),
