-- ----------------------------------------------------------------------------
-- Origem: common/V038__cria_tabela_pedido_fixo.sql
-- ----------------------------------------------------------------------------
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";
create table pedido_fixo(
	codigo uuid default uuid_generate_v4() not null primary key,
	codigo_cliente integer not null,
	codigo_categoria integer not null,
	descricao varchar(400) not null,
	data_para_execucao timestamptz not null,
	valor_fixo double precision not null,
	situacao varchar(20) not null default 'ABERTO',

	endereco_atendimento_logradouro varchar(50)  not null,
	endereco_atendimento_numero varchar(15)  not null,
	endereco_atendimento_cep varchar(20)  not null,
	endereco_atendimento_complemento varchar(30),
	endereco_atendimento_latitude decimal,
	endereco_atendimento_longitude decimal, 
	endereco_atendimento_bairro varchar(60)  not null,
	endereco_atendimento_codigo_cidade integer not null,	

	data_cadastro timestamptz not null,
	data_atualizacao timestamptz not null,
	codigo_usuario_cadastro integer not null,
	codigo_usuario_atualizacao integer not null,
	
	foreign key (codigo_cliente) references usuario(codigo),
	foreign key (endereco_atendimento_codigo_cidade) references cidade(codigo),
	foreign key (codigo_usuario_cadastro) references usuario(codigo),
	foreign key (codigo_usuario_atualizacao) references usuario(codigo),
	foreign key (codigo_categoria) references categoria_servico(codigo)
);


create table imagem_local_pedido_fixo(
	codigo_pedido uuid not null,
	codigo_imagem_local integer not null,
	foreign key (codigo_imagem_local) references imagem_local(codigo),
	foreign key (codigo_pedido) references pedido_fixo(codigo)
);


create table convite_pedido_fixo(
	codigo_pedido uuid not null,
	codigo_prestador integer not null,	
	data_entrada_fila timestamptz null,
	data_cancelamento timestamptz null,	
	situacao varchar(25) not null,
	motivo varchar,

	foreign key (codigo_prestador) references usuario(codigo),
	foreign key (codigo_pedido) references pedido_fixo(codigo),
	primary key(codigo_pedido,codigo_prestador)
);


-- ----------------------------------------------------------------------------
-- Origem: common/V039__cria-popula-tabela-bancos.sql
-- ----------------------------------------------------------------------------
create table banco (
       codigo serial primary key,
       codigo_banco varchar(3) not null,
       descricao varchar(100) not null,
       codigo_ispb varchar(8) not null
);


COMMENT ON TABLE pn10.banco IS 'Lista de códigos dos bancos
O Código do Banco é necessário para enviar ou receber transferências entre diferentes instituições financeiras. Exemplo: transferir dinheiro do Banco Itaú para o Bradesco; da Caixa para o Banco do Brasil, etc. O número do banco será necessário sempre que tentar fazer uma transferência via DOC (Documento de Ordem de Crédito) ou TED (Transferência Eletrônica Disponível).

O código do banco possui 3 dígitos.

A seguir listamos o código de todos os bancos brasileiros e instituições Lista de códigos dos bancos
O Código do Banco é necessário para enviar ou receber transferências entre diferentes instituições financeiras. Exemplo: transferir dinheiro do Banco Itaú para o Bradesco; da Caixa para o Banco do Brasil, etc. O número do banco será necessário sempre que tentar fazer uma transferência via DOC (Documento de Ordem de Crédito) ou TED (Transferência Eletrônica Disponível).

O código do banco possui 3 dígitos.

A seguir listamos o código de todos os bancos brasileiros e instituições financeiras cadastradas para receber transferências via DOC/TED. A lista também inclui o ISPB (Identificador do Sistema de Pagamento Brasileiro), cujo código é utilizado por alguns bancos na hora de efetivar uma transferência interbancária.

Como a lista é extensa dividimos em três colunas, na primeira você encontra o código de três dígitos que identifica o banco e/ou instituição financeira e na segunda coluna o nome da instituição. Por último temos o código ISPB, ele é pouco utilizado hoje em dia, mas ainda é solicitado por algumas instituições financeiras, dentre elas o Banco do Brasil e algumas cooperativas de crédito.';

